#!/bin/bash
# V5 finding probe: WORKFLOWS §31 (system/WORKFLOWS.md:988) says the UI's
# plugin/build-info.json is "generated by `npm run stage-plugin` or
# `npm run build` in obsidian-ui". Run both at the pinned UI checkout.
set -u
UI="$HOME/los-glm-V5-2026-10/obsidian-ui"
echo "UI pin: $(git -C "$UI" rev-parse HEAD)"
echo
echo '$ cd obsidian-ui && npm run stage-plugin'
cd "$UI" && npm run stage-plugin
echo "exit=$?"
echo
echo '$ cd obsidian-ui && npm run build'
npm run build > /dev/null 2>&1
echo "exit=$?"
echo "plugin/build-info.json exists afterwards: $([ -f plugin/build-info.json ] && echo yes || echo no)"
echo "git status --porcelain (empty = rebuilt outputs byte-identical, build-info gitignored):"
git status --porcelain
